// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 10 ether);

        vm.prank(alice);
        (bool success1, ) = address(c).call{value: 5 ether}("");
        require(success1, "first send failed");

        vm.prank(alice);
        (bool success2, ) = address(c).call{value: 3 ether}("");
        require(success2, "second send failed");

        assertTrue(c.balances(alice) == 8 ether);
    }
}
